class SlewGuard:
    def allow(self, actuator, new_sp, now):
        max_delta = SLEW_MAX[actuator] * (now - self.last_t[actuator])
        if abs(new_sp - self.last_sp[actuator]) > max_delta:
            return CLAMP_OR_REJECT      # never exceed hardware slew
